import { createStore } from "zustand/vanilla";
import { subscribeWithSelector } from "zustand/middleware";
import { slugify, uniqueSlug, type SlugCase } from "./slug";
import { blankNode, newId, type NodePatch, type SchemaNode } from "./tree";
import { defaultTypes, type TypeModule } from "./types";

/**
 * Normalized tree: a row subscribes to its own node only, so a keystroke
 * re-renders one row. The root is a node like any other (type object, key "").
 */

/** a node without its subtree, as stored */
export type NodeRecord = Omit<SchemaNode, "children">;
export type DetailField = "type" | "title" | "key" | "description" | "examples";

export type EditorState = {
  root: string;
  byId: Record<string, NodeRecord>;
  children: Record<string, string[]>;
  parentOf: Record<string, string>;
  types: TypeModule[];
  slugCase: SlugCase;
  /** ids currently selected */
  selected: string[];
  /** last id toggled by hand; shift-select ranges from it */
  anchor: string | null;
  /** live drag: where the row(s) would land; index counts siblings without the moving rows */
  drop: {
    id: string;
    /** everything that moves: the row, or the selection it belongs to */
    ids: string[];
    parentId: string;
    index: number;
    height: number;
  } | null;
  /** details dialog / sheet: which field, and which of its fields to show (all when omitted) */
  details: { id: string; fields?: DetailField[] } | null;

  replace: (root: SchemaNode) => void;
  update: (id: string, patch: NodePatch) => void;
  remove: (ids: string | string[]) => void;
  duplicate: (id: string) => string;
  insert: (parentId: string, type: string, index?: number) => string;
  /** reparent + reorder in one step; index is among siblings excluding the moved rows */
  move: (id: string | string[], parentId: string, index: number) => void;
  /** what a drag of `id` carries: the selection when `id` is part of it, else just `id` */
  moving: (id: string) => string[];
  select: (ids: string[]) => void;
  toggleSelect: (id: string, on?: boolean) => void;
  /** add every node between the anchor and `id` (document order) to the selection */
  selectRange: (id: string) => void;
  setDrop: (drop: EditorState["drop"]) => void;
  openDetails: (id: string | null, fields?: DetailField[]) => void;
};

export function fromNode(root: SchemaNode) {
  const byId: EditorState["byId"] = {};
  const children: EditorState["children"] = {};
  const parentOf: EditorState["parentOf"] = {};
  const walk = (n: SchemaNode, parent: string | null) => {
    const { children: kids, ...field } = n;
    byId[n.id] = field;
    if (parent) parentOf[n.id] = parent;
    if (n.isGroup) {
      children[n.id] = (kids ?? []).map((c) => c.id);
      for (const c of kids ?? []) walk(c, n.id);
    }
  };
  walk(root, null);
  return { root: root.id, byId, children, parentOf };
}

export function toNode(s: Pick<EditorState, "byId" | "children">, id: string): SchemaNode {
  const n = s.byId[id];
  return n.isGroup ? { ...n, children: (s.children[id] ?? []).map((c) => toNode(s, c)) } : { ...n };
}

/** ids in document order, root excluded */
export function docOrder(s: Pick<EditorState, "root" | "children">) {
  const out: string[] = [];
  const walk = (x: string) => {
    if (x !== s.root) out.push(x);
    for (const c of s.children[x] ?? []) walk(c);
  };
  walk(s.root);
  return out;
}

export function isDescendant(
  s: Pick<EditorState, "parentOf">,
  ancestor: string,
  id: string,
): boolean {
  for (let p = s.parentOf[id]; p; p = s.parentOf[p]) if (p === ancestor) return true;
  return false;
}

export function createEditorStore(
  root: SchemaNode,
  types: TypeModule[] = defaultTypes,
  slugCase: SlugCase = "camel",
) {
  return createStore<EditorState>()(
    subscribeWithSelector((set, get) => {
      const mod = (type: string) => get().types.find((t) => t.key === type);
      const taken = (s: EditorState, parent: string, except?: string) =>
        new Set(
          (s.children[parent] ?? []).filter((id) => id !== except).map((id) => s.byId[id].key),
        );

      const detach = (s: EditorState, id: string) => {
        const parent = s.parentOf[id];
        s.children[parent] = s.children[parent].filter((x) => x !== id);
      };
      const attach = (s: EditorState, id: string, parent: string, index?: number) => {
        const list = [...(s.children[parent] ?? [])];
        list.splice(index ?? list.length, 0, id);
        s.children[parent] = list;
        s.parentOf[id] = parent;
        const n = s.byId[id];
        const key = uniqueSlug(n.key, taken(s, parent, id), s.slugCase);
        if (key !== n.key) s.byId[id] = { ...n, key };
      };
      const drop = (s: EditorState, id: string) => {
        for (const c of s.children[id] ?? []) drop(s, c);
        delete s.byId[id];
        delete s.children[id];
        delete s.parentOf[id];
      };
      /** shallow-clone the maps we mutate so subscribers see new refs */
      const mutate = (fn: (s: EditorState) => void) =>
        set((prev) => {
          const s = {
            ...prev,
            byId: { ...prev.byId },
            children: { ...prev.children },
            parentOf: { ...prev.parentOf },
          };
          fn(s);
          s.selected = s.selected.filter((id) => s.byId[id]);
          return s;
        });

      return {
        ...fromNode(root),
        types,
        slugCase,
        selected: [],
        anchor: null,
        drop: null,
        details: null,

        replace: (root) =>
          set({
            ...fromNode(root),
            selected: [],
            anchor: null,
            drop: null,
            details: null,
          }),

        update: (id, patch) =>
          mutate((s) => {
            const prev = s.byId[id];
            const next = { ...prev, ...patch };
            if (patch.title !== undefined && !next.keyEdited && id !== s.root)
              next.key = uniqueSlug(
                slugify(next.title, s.slugCase),
                taken(s, s.parentOf[id], id),
                s.slugCase,
              );
            if (patch.key !== undefined) next.keyEdited = patch.key.length > 0;
            if (patch.type && patch.type !== prev.type) {
              const m = mod(patch.type);
              if (!m) return;
              next.isGroup = m.children;
              if (!m.examples) next.examples = [];
              // becoming a group needs a child list; leaving one drops the subtree
              if (m.children && !s.children[id]) s.children[id] = [];
              if (!m.children && s.children[id]) {
                for (const c of s.children[id]) drop(s, c);
                delete s.children[id];
              }
            }
            s.byId[id] = next;
          }),

        remove: (ids) =>
          mutate((s) => {
            for (const id of [ids].flat()) {
              if (id === s.root || !s.byId[id]) continue;
              detach(s, id);
              drop(s, id);
            }
          }),

        duplicate: (id) => {
          const nid = newId();
          mutate((s) => {
            const parent = s.parentOf[id];
            const clone = (x: string, into: string, forced?: string): string => {
              const cid = forced ?? newId();
              s.byId[cid] = { ...s.byId[x], id: cid };
              s.parentOf[cid] = into;
              if (s.children[x]) s.children[cid] = s.children[x].map((c) => clone(c, cid));
              return cid;
            };
            clone(id, parent, nid);
            s.byId[nid] = { ...s.byId[nid], keyEdited: true };
            attach(s, nid, parent, s.children[parent].indexOf(id) + 1);
          });
          return nid;
        },

        insert: (parentId, type, index) => {
          const m = mod(type);
          if (!m) throw new Error(`unknown type "${type}"`);
          const node = blankNode(type, m.children, {
            key: slugify(m.label, get().slugCase) || "field",
          });
          mutate((s) => {
            const { children: _c, ...field } = node;
            s.byId[node.id] = field;
            if (m.children) s.children[node.id] = [];
            attach(s, node.id, parentId, index);
          });
          return node.id;
        },

        move: (id, parentId, index) => {
          const s = get();
          const want = new Set([id].flat());
          // document order; a row inside another moved row travels with it
          const ids = docOrder(s).filter(
            (x) => want.has(x) && !Array.from(want).some((a) => a !== x && isDescendant(s, a, x)),
          );
          if (!ids.length || !s.children[parentId]) return;
          if (ids.some((x) => x === parentId || isDescendant(s, x, parentId))) return;
          mutate((s) => {
            for (const x of ids) detach(s, x);
            ids.forEach((x, i) => attach(s, x, parentId, index + i));
          });
        },
        moving: (id) => {
          const s = get();
          return s.selected.includes(id) ? s.selected : [id];
        },

        select: (selected) => set({ selected }),
        toggleSelect: (id, on) =>
          set((s) => {
            const has = s.selected.includes(id);
            const next = on ?? !has;
            return {
              anchor: id,
              selected: next
                ? has
                  ? s.selected
                  : [...s.selected, id]
                : s.selected.filter((x) => x !== id),
            };
          }),

        selectRange: (id) => {
          const s = get();
          if (!s.anchor || !s.byId[s.anchor]) return s.toggleSelect(id, true);
          const order = docOrder(s);
          const [a, b] = [order.indexOf(s.anchor), order.indexOf(id)].sort((x, y) => x - y);
          const range = order.slice(a, b + 1);
          set({
            selected: [...s.selected, ...range.filter((x) => !s.selected.includes(x))],
          });
        },

        setDrop: (drop) => {
          const cur = get().drop;
          if (
            cur === drop ||
            (cur && drop && cur.parentId === drop.parentId && cur.index === drop.index)
          )
            return;
          set({ drop });
        },
        openDetails: (id, fields) => set({ details: id ? { id, fields } : null }),
      };
    }),
  );
}

export type EditorStore = ReturnType<typeof createEditorStore>;

import { createEditorStore, toNode, type EditorStore } from "./editor";
import { fromJsonSchema, toExample as example, toJsonSchema } from "./schema";
import type { SlugCase } from "./slug";
import type { NodePatch, SchemaNode } from "./tree";
import { defaultTypes, type Json, type TypeModule } from "./types";

export type JsonSchemaOptions = { types?: TypeModule[]; slugCase?: SlugCase };

/**
 * The handle: a ref-like object the owner keeps. Stable identity, never
 * re-renders anything by itself; rows subscribe to their own node, the owner
 * pulls with `toJSON()` or opts into `subscribe`.
 */
export type JsonSchema = ReturnType<typeof createJsonSchema>;

export function createJsonSchema(
  json: Json,
  { types = defaultTypes, slugCase = "camel" }: JsonSchemaOptions = {},
) {
  const store: EditorStore = createEditorStore(fromJsonSchema(json, types), types, slugCase);
  const s = () => store.getState();
  const node = (id: string) => (s().byId[id] ? toNode(s(), id) : undefined);
  // same tree → same JSON object, so useSyncExternalStore sees a stable snapshot
  let cache: { byId: unknown; children: unknown; json: Json } | null = null;
  const toJSON = (): Json => {
    const { byId, children, root } = s();
    if (!cache || cache.byId !== byId || cache.children !== children)
      cache = { byId, children, json: toJsonSchema(toNode(s(), root), types) };
    return cache.json;
  };

  return {
    store,
    types,
    get root() {
      return s().root;
    },
    toJSON,
    toExample: () => example(toNode(s(), s().root), types),
    /** fires after every tree change with the new JSON */
    subscribe: (fn: (json: Json) => void) =>
      store.subscribe(
        (st) => [st.byId, st.children] as const,
        () => fn(toJSON()),
        { equalityFn: (a, b) => a[0] === b[0] && a[1] === b[1] },
      ),
    reset: (json: Json) => s().replace(fromJsonSchema(json, types)),

    get: node,
    /** id by key path, e.g. "address.street" */
    find: (path: string): string | undefined => {
      let id = s().root;
      for (const key of path.split(".")) {
        const next = (s().children[id] ?? []).find((c) => s().byId[c].key === key);
        if (!next) return undefined;
        id = next;
      }
      return id;
    },
    update: (id: string, patch: NodePatch) => s().update(id, patch),
    insert: (parentId: string, type: string, index?: number) => s().insert(parentId, type, index),
    move: (id: string | string[], parentId: string, index: number) => s().move(id, parentId, index),
    remove: (ids: string | string[]) => s().remove(ids),
    duplicate: (id: string) => s().duplicate(id),

    select: (ids: string[]) => s().select(ids),
    selected: (): string[] => s().selected,
    removeSelected: () => s().remove(s().selected),
  };
}

export type { SchemaNode };

export { createJsonSchema, type JsonSchema, type JsonSchemaOptions } from "./handle";
export { fromJsonSchema, toExample, toJsonSchema } from "./schema";
export { defineType, defaultTypes, typeGroups, types, type Json, type TypeModule } from "./types";
export type { Field, FieldPatch, NodePatch, SchemaNode } from "./tree";
export { validate } from "./validate";

import { slugify } from "./slug";
import { blankNode, parseIds, type SchemaNode } from "./tree";
import { defaultTypes, type Json, type TypeModule } from "./types";

const META = ["title", "description", "examples"] as const;
/** keywords the node model owns; anything else is `extra` */
const MODELED = [
  "type",
  "format",
  "const",
  "properties",
  "required",
  "additionalProperties",
  "oneOf",
  "anyOf",
  "items",
];

export const registry = (types: TypeModule[]) => new Map(types.map((t) => [t.key, t]));

/* ------------------------------- tree → json ------------------------------ */

/** node tree → JSON Schema (draft 2020-12). Root must be an object node. */
export function toJsonSchema(root: SchemaNode, types: TypeModule[] = defaultTypes): Json {
  return nodeSchema(root, registry(types));
}

function nodeSchema(n: SchemaNode, reg: Map<string, TypeModule>): Json {
  const mod = reg.get(n.type);
  if (!mod) throw new Error(`unknown type "${n.type}"`);
  let s: Json = { ...mod.schema(n) };
  if (n.type === "object") {
    const properties: Json = {};
    const required: string[] = [];
    for (const c of n.children ?? []) {
      properties[c.key] = nodeSchema(c, reg);
      if (!c.optional) required.push(c.key);
    }
    s.properties = properties;
    if (required.length) s.required = required;
    s.additionalProperties = false;
  } else if (mod.children) {
    s.oneOf = (n.children ?? []).map((c) => nodeSchema(c, reg));
  }
  if (n.title) s.title = n.title;
  if (n.description) s.description = n.description;
  if (mod.examples && n.examples.length) s.examples = n.examples;
  Object.assign(s, n.extra);
  if (n.nullable) {
    if (typeof s.type === "string" && !mod.children) s.type = [s.type, "null"];
    else {
      const { title, description, examples, ...inner } = s;
      s = { anyOf: [inner, { type: "null" }] };
      if (title !== undefined) s.title = title;
      if (description !== undefined) s.description = description;
      if (examples !== undefined) s.examples = examples;
    }
  }
  if (n.repeated) s = { type: "array", items: s, ...(n.title ? { title: n.title } : {}) };
  return s;
}

/* ------------------------------- json → tree ------------------------------ */

/** JSON Schema → node tree. Unknown keywords are kept on `node.extra`. */
export function fromJsonSchema(json: Json, types: TypeModule[] = defaultTypes): SchemaNode {
  const root = parse(json, "", types, false, parseIds());
  if (root.type !== "object") throw new Error("root schema must be an object");
  root.key = "";
  return root;
}

function parse(
  input: Json,
  key: string,
  types: TypeModule[],
  optional: boolean,
  nextId: () => string,
): SchemaNode {
  let s = input;
  const flags = { nullable: false, repeated: false };

  if (s.type === "array" && s.items && typeof s.items === "object") {
    flags.repeated = true;
    const { items, type: _t, title, ...rest } = s;
    s = { ...(items as Json), ...rest };
    if (title !== undefined && s.title === undefined) s.title = title;
  }
  if (Array.isArray(s.type) && s.type.includes("null")) {
    flags.nullable = true;
    const t = s.type.filter((x) => x !== "null");
    s = { ...s, type: t.length === 1 ? t[0] : t };
  } else if (
    Array.isArray(s.anyOf) &&
    s.anyOf.length === 2 &&
    (s.anyOf[1] as Json)?.type === "null"
  ) {
    flags.nullable = true;
    const { anyOf, ...rest } = s;
    s = { ...(anyOf[0] as Json), ...rest };
  }

  const mod = pickType(s, types);
  const title = typeof s.title === "string" ? s.title : "";
  const derived = title ? slugify(title, "camel") : "";
  const node = blankNode(mod.key, mod.children, {
    id: nextId(),
    key: mod.key === "const" ? String(s.const) : key || derived,
    // keys that came from JSON are real property names: never renamed by a title edit
    keyEdited: !!key,
    title,
    description: typeof s.description === "string" ? s.description : "",
    examples: mod.examples && Array.isArray(s.examples) ? s.examples.map(String) : [],
    optional,
    ...flags,
  });

  if (mod.key === "object") {
    const props = (s.properties ?? {}) as Record<string, Json>;
    const required = (s.required ?? []) as string[];
    node.children = Object.entries(props).map(([k, v]) =>
      parse(v, k, types, !required.includes(k), nextId),
    );
  } else if (mod.children) {
    node.children = ((s.oneOf ?? []) as Json[]).map((v) => parse(v, "", types, false, nextId));
  }
  // everything the editor does not model rides along; type modules read what they need from it
  const consumed = new Set<string>([...META, ...MODELED]);
  const extra = Object.fromEntries(Object.entries(s).filter(([k]) => !consumed.has(k)));
  if (Object.keys(extra).length) node.extra = extra;
  return node;
}

/**
 * Most specific matching module wins: the one claiming the most keys of the
 * schema (e.g. a `pattern` type beats plain string). Ties → registry order.
 */
function pickType(s: Json, types: TypeModule[]): TypeModule {
  let best: { mod: TypeModule; n: number } | null = null;
  for (const mod of types) {
    if (!mod.matches(s)) continue;
    const probe = blankNode(mod.key, mod.children, { extra: s });
    const claims = new Set(Object.keys(mod.schema(probe)));
    if (mod.children)
      for (const k of ["properties", "required", "additionalProperties", "oneOf"]) claims.add(k);
    const n = Object.keys(s).filter((k) => claims.has(k)).length;
    if (!best || n > best.n) best = { mod, n };
  }
  return best?.mod ?? types.find((t) => t.key === "string")!;
}

/* --------------------------------- example -------------------------------- */

/** node tree → plausible example document */
export function toExample(root: SchemaNode, types: TypeModule[] = defaultTypes): unknown {
  return example(root, registry(types));
}

function example(n: SchemaNode, reg: Map<string, TypeModule>): unknown {
  const mod = reg.get(n.type)!;
  let v: unknown;
  if (n.type === "object")
    v = Object.fromEntries((n.children ?? []).map((c) => [c.key, example(c, reg)]));
  else if (mod.children) v = n.children?.[0] ? example(n.children[0], reg) : null;
  else v = mod.example(n);
  return n.repeated ? [v] : v;
}

export type SlugCase = "kebab" | "camel" | "snake";

const words = (s: string) =>
  s
    .normalize("NFKD")
    .replace(/[̀-ͯ]/g, "")
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .replace(/[^\p{L}\p{N}]+/gu, " ")
    .trim()
    .split(/\s+/)
    .filter(Boolean)
    .map((w) => w.toLowerCase());

/** "Created at" → created-at | createdAt | created_at */
export function slugify(title: string, kase: SlugCase): string {
  const w = words(title);
  if (!w.length) return "";
  switch (kase) {
    case "kebab":
      return w.join("-");
    case "snake":
      return w.join("_");
    case "camel":
      return (
        w[0] +
        w
          .slice(1)
          .map((x) => x[0].toUpperCase() + x.slice(1))
          .join("")
      );
  }
}

const suffixSep: Record<SlugCase, string> = {
  kebab: "-",
  snake: "_",
  camel: "",
};

/** first of base, base2, base3… (sep per case) not in taken */
export function uniqueSlug(base: string, taken: Set<string>, kase: SlugCase): string {
  if (!base || !taken.has(base)) return base;
  // strip an existing numeric suffix so "email2" → "email" → "email3"
  const sep = suffixSep[kase];
  const root = base.replace(new RegExp(`${sep ? "\\" + sep : ""}\\d+$`), "") || base;
  for (let n = 2; n < 1000; n++) {
    const candidate = `${root}${sep}${n}`;
    if (!taken.has(candidate)) return candidate;
  }
  return base;
}

/** One field. Root is an object node with key "". */
export type SchemaNode = {
  id: string;
  type: string;
  /** JSON key (property name / const value); auto from title until edited by hand */
  key: string;
  keyEdited: boolean;
  title: string;
  description: string;
  examples: string[];
  optional: boolean;
  nullable: boolean;
  /** array of this field */
  repeated: boolean;
  collapsed?: boolean;
  /** JSON Schema keywords the editor has no UI for; written back untouched */
  extra?: Record<string, unknown>;
  /** derived from the type module */
  isGroup: boolean;
  children?: SchemaNode[];
};

export type NodePatch = Partial<Omit<SchemaNode, "id" | "isGroup" | "children">>;

/** the node as the hooks hand it out: subtree under `fields` */
export type Field = Omit<SchemaNode, "children"> & { fields?: Field[] };
export type FieldPatch = NodePatch;

let seq = 0;
/** runtime ids (insert / duplicate) */
export const newId = () => `x${Date.now().toString(36)}${(seq++).toString(36)}`;
/** deterministic ids for parsed trees, so server and client render the same DOM */
export const parseIds = () => {
  let n = 0;
  return () => `n${++n}`;
};

export function blankNode(
  type: string,
  isGroup: boolean,
  over: Partial<SchemaNode> = {},
): SchemaNode {
  return {
    id: newId(),
    type,
    key: "",
    keyEdited: false,
    title: "",
    description: "",
    examples: [],
    optional: false,
    nullable: false,
    repeated: false,
    isGroup,
    ...(isGroup ? { children: [] } : {}),
    ...over,
  };
}

import type { ComponentType } from "react";
import {
  ALargeSmallIcon,
  BinaryIcon,
  BracesIcon,
  CalendarIcon,
  CircleSlashIcon,
  EqualIcon,
  HashIcon,
  LinkIcon,
  MailIcon,
  SplitIcon,
  ToggleLeftIcon,
  type LucideIcon,
} from "lucide-react";
import type { SchemaNode } from "./tree";

export type Json = Record<string, unknown>;

/**
 * A type is a module: everything type-specific lives here, the editor never
 * branches on `node.type`. Register custom ones through `createJsonSchema(json, { types })`.
 */
export type TypeModule = {
  key: string;
  label: string;
  description: string;
  icon: LucideIcon;
  /** tailwind classes for the icon tile; colours come from --type-* tokens */
  color: string;
  /** node → JSON Schema (without title / description / examples / extra) */
  schema: (node: SchemaNode) => Json;
  /** node → plausible example value */
  example: (node: SchemaNode) => unknown;
  /** parsing: does this module own the given schema? first match in registry order wins */
  matches: (schema: Json) => boolean;
  /** has child nodes (object properties, choice alternatives) */
  children: boolean;
  /** which child types may be dropped inside; true = any */
  accepts: readonly string[] | boolean;
  /** takes example values */
  examples: boolean;
  /** badge text for the child count */
  countLabel?: (n: number) => string;
  /** optional type-owned UI rendered in the row */
  Extra?: ComponentType<{
    node: SchemaNode;
    set: (patch: Partial<SchemaNode>) => void;
  }>;
};

type Optional = "children" | "accepts" | "examples" | "matches" | "example";

export function defineType(
  def: Omit<TypeModule, Optional> & Partial<Pick<TypeModule, Optional>>,
): TypeModule {
  return {
    children: false,
    accepts: false,
    examples: true,
    matches: (s) => s.type === def.key,
    example: (n) => n.examples[0] ?? "",
    ...def,
  };
}

