/**
 * Moves the targets to the end of a picked group. Targets, their subtrees and
 * leaves are not offered. Bulk-only by design, but works in a row too.
 */
export function MoveInto({
  topLabel = "Top level",
  ...props
}: ActionProps & { topLabel?: string }) {
  const { store, types } = useEditor();
  const ids = useActionTargets();
  const groups = useEditorStore(
    useShallow((s) =>
      Object.keys(s.byId).filter(
        (id) => s.byId[id].isGroup && !ids.includes(id) && !ids.some((x) => isDescendant(s, x, id)),
      ),
    ),
  );
  const s = store.getState();
  const label = (id: string) => (id === s.root ? topLabel : s.byId[id].title || s.byId[id].key);
  return (
    <Menu
      title="Move into"
      trigger={
        <ActionPrimitive icon={FolderInputIcon} label="Move into" run={() => {}} {...props} />
      }
    >
      {groups.map((id) => (
        <MoveTarget
          key={id}
          id={id}
          label={label(id)}
          onPick={() => {
            for (const x of ids) store.getState().move(x, id, store.getState().children[id].length);
          }}
        />
      ))}
    </Menu>
  );
}

function MoveTarget({ id, label, onPick }: { id: string; label: string; onPick: () => void }) {
  const mod = useTypeModule(useEditorStore((s) => s.byId[id].type));
  const menu = React.useContext(MenuContext);
  return (
    <MenuItem
      onClick={() => {
        onPick();
        menu?.close();
      }}
    >
      <IconTile icon={mod.icon} color={mod.color} size="sm" />
      <span className="min-w-0 flex-1 truncate">{label}</span>
    </MenuItem>
  );
}

/**
 * Opens the field's details (title, key, description, examples) in a dialog,
 * or a sheet on mobile. The overlay is mounted by the row, so this works from
 * inside a menu that closes on click.
 */
export function EditDetails({ fields, ...props }: ActionProps & { fields?: DetailField[] }) {
  const { store } = useEditor();
  const field = useFieldOptional();
  if (!field) throw new Error("<SchemaAction.EditDetails> must be inside a row");
  return (
    <ActionPrimitive
      icon={PencilLineIcon}
      label="Edit details"
      run={() => store.getState().openDetails(field.id, fields)}
      {...props}
    />
  );
}

"use client";

import * as React from "react";
import { useStore } from "zustand";
import type { EditorState, EditorStore } from "@/registry/base-nova/ui/json/core/editor";
import type {
  JsonSchema,
  NodePatch,
  SchemaNode,
  TypeModule,
} from "@/registry/base-nova/ui/json/core";

export type Variant = "default" | "compact" | "wide" | "mobile";

/* --------------------------------- editor -------------------------------- */

export type EditorCtx = {
  schema: JsonSchema;
  store: EditorStore;
  types: TypeModule[];
  /** editor element; drag hit-tests query rows under it */
  root: React.RefObject<HTMLDivElement | null>;
  /** coarse pointer detected → lists default to `mobile` */
  coarse: boolean;
  /** where popups (menus, sheets, dialogs) portal to; default document body */
  portal?: React.RefObject<HTMLElement | null>;
};
export const EditorContext = React.createContext<EditorCtx | null>(null);

export function useEditor() {
  const ctx = React.useContext(EditorContext);
  if (!ctx) throw new Error("Schema parts must be inside <Schema.Root>");
  return ctx;
}

/** subscribe to a slice of the store */
export function useEditorStore<T>(selector: (s: EditorState) => T): T {
  return useStore(useEditor().store, selector);
}

export const useTypeModule = (type: string) => {
  const { types } = useEditor();
  const mod = types.find((t) => t.key === type);
  if (!mod) throw new Error(`unknown type "${type}"`);
  return mod;
};

/* ---------------------------------- list --------------------------------- */

export type RenderRow = (node: SchemaNode) => React.ReactNode;

export type ListCtx = {
  parentId: string;
  depth: number;
  variant: Variant;
  /** how rows in this list (and nested ones, by default) are drawn */
  render: RenderRow;
  /** inside the drag ghost: render only, no drag / hit-test participation */
  ghost?: boolean;
  /** <Schema.Column> cells every row draws beside its content; nested lists inherit */
  columns?: { left: React.ReactElement[]; right: React.ReactElement[] };
  /** the grid this list's rows are laid on: [left | content | right] when columns are declared */
  cols: 1 | 3;
};
export const ListContext = React.createContext<ListCtx | null>(null);
export const useList = () => {
  const ctx = React.useContext(ListContext);
  if (!ctx) throw new Error("row parts must be inside <Schema.List>");
  return ctx;
};
/** variant outside a list (a toolbar's), set by <Schema.Toolbar variant> */
export const VariantContext = React.createContext<Variant | null>(null);
/** list variant; outside a list the toolbar's, else "default" */
export const useVariant = (): Variant => {
  const list = React.useContext(ListContext);
  const outer = React.useContext(VariantContext);
  return list?.variant ?? outer ?? "default";
};

/* ---------------------------------- field -------------------------------- */

/** id of the node a <SchemaField.Row> draws; set by the list per row */
export const RowIdContext = React.createContext<string | null>(null);

export type FieldCtx = {
  id: string;
  /** a <SchemaField.Handle> is mounted → the row drags only from it */
  hasHandle: boolean;
  setHasHandle: (on: boolean) => void;
  /** drag start, wired by Row */
  startDrag: (e: React.PointerEvent | PointerEvent) => void;
};
export const FieldContext = React.createContext<FieldCtx | null>(null);

/** current row, internal: node + patch + drag wiring. Parts that only need the model use hooks.useField */
export function useFieldContext() {
  const ctx = React.useContext(FieldContext);
  if (!ctx) throw new Error("field parts must be inside <SchemaField.Row>");
  const { store } = useEditor();
  const node = useStore(store, (s) => s.byId[ctx.id]);
  const set = React.useCallback(
    (patch: NodePatch) => store.getState().update(ctx.id, patch),
    [store, ctx.id],
  );
  return { ...ctx, node, set };
}
export const useFieldOptional = () => React.useContext(FieldContext);

/* -------------------------------- scopes --------------------------------- */

/** where an action renders decides its look and its targets */
export type ActionScope = "row" | "menu" | "toolbar";
export const ActionScopeContext = React.createContext<ActionScope>("row");
export const useActionScope = () => React.useContext(ActionScopeContext);

/** true under <Schema.Toolbar>: actions there (menus included) apply to the selection */
export const ToolbarContext = React.createContext(false);

/** ids an action applies to: the field, or the selection inside a toolbar */
export function useActionTargets(): string[] {
  const scope = useActionScope();
  const toolbar = React.useContext(ToolbarContext);
  const field = useFieldOptional();
  const selected = useEditorStore((s) => s.selected);
  if (scope === "toolbar" || toolbar) return selected;
  if (!field) throw new Error("actions outside a toolbar must be inside <SchemaField.Row>");
  return [field.id];
}

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import { useRender } from "@base-ui/react/use-render";

export type RenderProp = Parameters<typeof useRender>[0]["render"];

export type EditableProps = Omit<React.ComponentProps<"input">, "value" | "onChange"> & {
  value: string;
  onChange: (v: string) => void;
  /** fired on blur / Enter with final value */
  onCommit?: (v: string) => void;
  multiline?: boolean;
  /** render as plain text (mobile summaries) */
  readOnly?: boolean;
  /** your own element (e.g. shadcn <Input />); value / handlers merged in, none of our styling */
  render?: RenderProp;
  /** `inline`: plain text until hover / focus. `input`: a bordered field */
  variant?: "inline" | "input";
};

/** Inline text edit: an input styled as plain text, sized to its content. */
export function Editable({
  value,
  onChange,
  onCommit,
  multiline,
  readOnly,
  className,
  render,
  variant = "inline",
  ...rest
}: EditableProps) {
  const onKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if ((e.key === "Enter" && !(multiline && e.shiftKey)) || e.key === "Escape") {
      e.preventDefault();
      e.currentTarget.blur();
    }
  };
  const custom = useRender({
    render,
    enabled: !!render,
    defaultTagName: multiline ? "textarea" : "input",
    props: {
      ...(rest as object),
      value,
      onChange: (e: React.ChangeEvent<HTMLInputElement>) => onChange(e.target.value),
      onBlur: (e: React.FocusEvent<HTMLInputElement>) => onCommit?.(e.target.value),
      onKeyDown,
      className,
    },
  });
  if (render && !readOnly) return custom;
  if (readOnly)
    return (
      <span
        {...(rest as React.ComponentProps<"span">)}
        className={cn("truncate", !value && "text-muted-foreground/60", className)}
      >
        {value || rest.placeholder}
      </span>
    );
  const Tag = (multiline ? "textarea" : "input") as "input";
  return (
    <Tag
      {...(rest as React.ComponentProps<"input">)}
      {...(multiline ? { rows: 1 } : {})}
      data-variant={variant}
      value={value}
      onChange={(e) => onChange(e.target.value)}
      onBlur={(e) => onCommit?.(e.target.value)}
      onKeyDown={onKeyDown}
      className={cn(
        "resize-none rounded-md outline-none placeholder:text-muted-foreground/60",
        variant === "inline"
          ? // padding with matching negative margins: breathing room on hover / focus, no layout shift.
            // max width includes the margins, else a percentage clamp eats the last character
            "-mx-1.5 -my-0.5 field-sizing-content max-w-[calc(100%+--spacing(3))] min-w-6 bg-transparent px-1.5 py-0.5 hover:bg-muted/50 focus:bg-muted/70"
          : "w-full border border-input bg-background px-2 py-1 shadow-xs focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50",
        className,
      )}
    />
  );
}

