/** the ⋯ menu; children are SchemaAction.* (or anything) */
export function MenuPart({
  className,
  children,
  label = "Field settings",
}: Part & { children: React.ReactNode; label?: string }) {
  const { field: node } = useField();
  const v = useVariant();
